('node-1-21', 'phase-01-lesson-21-dataclasses-dataclass-boilerplate-reducti', 'module-2', 21, 'Lesson 2.21: Dataclasses: @dataclass Boilerplate Reduction', 'Prerequisites: Lesson 1.2', 'Prerequisites: Lesson 1.2 | Subtopics: 4 items', 'Systems project application', 120, 2, 250.0, 1050.0, '# Lesson 1.21: Dataclasses: @dataclass Boilerplate Reduction

